return ['po-revision-date'=>'2026-08-21 12:49:11+0000','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','plural-forms'=>'nplurals=2; plural=n != 1;','x-generator'=>'GlotPress/4.1.0','language'=>'nb_NO','project-id-version'=>'Plugins - Login with Vipps and MobilePay - Development (trunk)','messages'=>['!'=>'!','%1$s integration settings'=>'Integrasjonsinnstillinger for %1$s','%1$s user with phone %2$s just connected to account %1$d'=>'%1$s-bruker med telefon %2$s koblet akkurat til konto %1$d','%1$s user with phone %2$s just connected to account %3$d during account creation'=>'%1$s-bruker med telefon %2$s koblet akkurat til konto %3$d under oppretting av konto','%1$s user with phone %2$s just connected to account %3$d during login'=>'%1$s-bruker med telefon %2$s koblet akkurat til konto %3$d under innlogging','<a href=\'%s\'>Return to your previous page</a> to try again</a>'=>'<a href=\'%s\'>Gå tilbake til forrige side</a> for å prøve igjen</a>','A problem occurred when getting user info from %1$s:'=>'Det oppsto et problem med å motta brukerinformasjon fra %1$s:','A problem occurred when trying to use %1$s:'=>'Det oppsto et problem med å bruke %1$s:','API keys'=>'API-nøkler','Add %1$s to login page'=>'Legg %1$s til innloggingssiden','Add a "Continue with %s" button'=>'Legg til en «Fortsett med %s»-knapp','Advanced'=>'Avansert','Allow users to register as customers in WooCommerce using Login with %1$s'=>'Tillat brukere å registrere seg som kunder i WooCommerce med Innlogging med %1$s','An unknown or unavailable setting was submitted.'=>'En ukjent eller utilgjengelig innstilling ble sendt inn.','Application'=>'Applikasjon','Are you registered as a customer? Log in with %s to continue your checkout.'=>'Er du registrert som kunde? Logg inn med %s for å fortsette til kassen.','Are you registered as a customer? Log in with %s.'=>'Er du registrert som kunde? Logg inn med %s.','As long as your profile is connected to %1$s, you can log in with %1$s.'=>'Så lenge kontoen din er koblet til %1$s, kan du logge inn med %1$s.','Cannot disconnect'=>'Kan ikke koble fra','Cannot log in: It is required for this account to verify login with the %1$s app'=>'Kan ikke logge inn: For denne kontoen er det nødvendig å bekrefte innloggingen din med %1$s-appen','Cannot redirect to %1$s waiting page as it doesn\'t exist. If you just tried to log in, check your email.'=>'Kan ikke omdirigere til ventesiden for %1$s fordi den ikke eksisterer. Om du nettopp prøvde å logge inn, sjekk e-posten din.','Change "Continue with %1$s" banner link text'=>'Endre lenketeksten på banneret "Fortsett med %1$s"','Change "Continue with %1$s" banner text'=>'Endre teksten på banneret "Fortsett med %1$s"','Choose the country to use for Login.'=>'Velg landet som skal brukes for innlogging.','Choose which login method you\'d like to enable for your users.'=>'Velg hvilken måte å logge inn på du vil slå på for brukerne dine.','Click here to continue'=>'Trykk her for å fortsette','Click to continue'=>'Klikk for å fortsette','Client ID'=>'Client ID','Client Secret'=>'Client Secret','Compact'=>'Kompakt','Connection to %1$s profile %2$s <b>removed</b>.'=>'Koblingen til %1$s-profilen %2$s <b>fjernet</b>.','Continue'=>'Fortsett','Continue with %1$s page'=>'Fortsett med %1$s-side','Continue with %s'=>'Fortsett med %s','Copy the URI above. Then go to <a target="_blank" href="%s">https://portal.vippsmobilepay.com</a> and choose "Developer". Find your point of sale and press "Setup login". Press "Activate Login" and paste the URI into the field "URI". Then press "Save". If you change your websites name or your permalink setup, you will need to register the new URI the same way.'=>'Kopier URI-en til ovenfor. Gå til <a target="_blank" href="%s">https://portal.vippsmobilepay.com</a> og velg "Developer". Finn salgsstedet ditt og trykk "Setup login". Klikk «Activate Login» og lim inn URI-en i feltet "URI". Klikk så "Save". Om du endrer nettstedsnavnet eller oppsettet for permalenkene på nettstedet ditt, må du registrere den nye URI-en på samme måte.','Could not connect to your %1$s profile: '=>'Kunne ikke koble til med %1$s-profilen: ','Could not create a new user - an error occured: %s'=>'Kunne ikke opprette en ny bruker - det oppsto en feil: %s','Could not create session table. The Login with %1$s plugin is not correctly installed.'=>'Kunne ikke opprette tabellen "session". Utvidelsen Innlogging med %1$s er ikke korrekt innstallert.','Could not create user identity table. The Login with %1$s plugin is not correctly installed.'=>'Kunne ikke opprette brukeridentitetstabell. Utvidelsen Innlogging med %1$s er ikke korrekt installert.','Could not find any user with your registered email. Cannot log in.'=>'Kunne ikke finne noen bruker med din registrerte e-postadresse. Kan ikke logge deg inn.','Could not find or create the "Continue with %1$s" page.'=>'Fant ikke eller kunne ikke opprette siden "Fortsett med %1$s".','Could not save settings. Please try again.'=>'Kunne ikke lagre innstillingene. Prøv igjen.','Could not synchronize your %1$s profile: '=>'Kunne ikke synkronisere med din %1$s-profil: ','Could not verify your oAuth2 token: %s'=>'Kunne ikke verifisere din oAuth2 token: %s','Country'=>'Land','Create a new page'=>'Lag ny side','Create an account using %s'=>'Lag en ny konto med %s','Danish'=>'Dansk','Dark'=>'Mørk','Denmark'=>'Danmark','Dismissed message '=>'Avvist melding','Enable Login with %1$s'=>'Slå på Innlogging med %1$s','Enable Login with %1$s for WooCommerce'=>'Slå på på Innlogging med %1$s for WooCommerce','Enable Login with %1$s on your customer\'s pages in WooCommerce'=>'Slå på Innlogging med %1$s på kundesiden i WooCommerce','Enable new users to be created as customers if using Login with %1$s with WooCommerce. If you are using the payment gateway, this will have been configured to create new users when using Express Checkout - checkout the payment gateway settings to modify this.'=>'Tillat nye brukere å bli opprettet som kunder om du bruker Innlogging med %1$s sammen med WooCommerce. Hvis du bruker betalingsporten, vil denne nå bli konfigurert til å opprette nye brukere når de handler med hurtigkassen - se innstillingene for betalingsporten for å endre dette.','English'=>'Engelsk','Everybody'=>'Alle','Finland'=>'Finland','Finnish'=>'Finsk','General'=>'Generelt','Get addresses'=>'Hent adresser','Go to <a target="_blank" href="%s">https://portal.vippsmobilepay.com</a> and choose "Developer". Find your point of sale and press "Show keys". Copy the value of "client id" and paste it into this field'=>'Gå til <a target="_blank" href="%s">https://portal.vippsmobilepay.com</a>  og velg "Utvikler". Finn salgsstedet ditt og trykk "Show keys". Kopier verdien fra «client_id» og lim den inn i dette feltet.','Go to <a target="_blank" href="%s">https://portal.vippsmobilepay.com</a> and choose "Developer". Find your point of sale and press "Show keys". Copy the value of "client secret" and paste it into this field'=>'Gå til <a target="_blank" href="%s">https://portal.vippsmobilepay.com</a>  og «Utvikler». Finn salgsstedet ditt og  trykk på "Show keys". Kopier verdien for "client_secret" og lim den inn i dette feltet.','Having downloaded Log in with %1$s: It is quick and easy to get started! Get your API keys in the %1$s Portal and add them to the plugin to activate Log in with %1$s.'=>'Til deg som har lastet ned utvidelsen Logg inn med %1$s: Det er raskt og enkelt å komme i gang! Hent API-nøklene dine i %1$s-portalen og legg dem inn i utvidelsen for å aktivere Logg inn med %1$s.','Hide'=>'Skjul','If you are using Express Checkout, that will be shown instead.'=>'Om du bruker hurtigkasse, vil den bli vist i stedet.','If you check this, this user will not be allowed to log in without confirming this operation with their %1$s app - email addresses must match.'=>'Hvis du huker av dette, vil brukeren ikke kunne logge inn uten å bekrefte innloggingen med %1$s-appen sin. E-postadressene må stemme overens.','Installed database tables for Login With %1$s'=>'Installerte databasetabeller for Innlogging med %1$s','Insufficient privileges'=>'Ikke tilstrekkelige tillatelser','Invalid code parameters passed.'=>'Ugyldige kodeparametere ble sendt inn.','It is unfortunately not allowed for your account to log-in using %1$s'=>'Det er dessverre ikke tillatt for din konto å bruke %1$s til å logge inn med','It is unfortunately not possible for your account to use %1$s to log in to this system due to the site administrators policy.'=>'Det er dessverre ikke mulig for din konto å bruke %1$s til å logge inn på dette systemet på grunn av regler bestemt av administratoren for nettstedet.','Language'=>'Språk','Light'=>'Lys','Log in or register an account using %1$s.'=>'Logg eller registrer en konto med %1$s.','Log in or register an account using %s.'=>'Logg inn eller registrer en konto med %s.','Log in or register an account with %s to continue your checkout.'=>'Logg inn eller registrer en konto med %s for å fortsette til kassen.','Log in to WooCommerce'=>'Logg inn i WooCommerce','Log in to WordPress'=>'Logg inn i WordPress','Log in with'=>'Logg inn med','Log in with %1$s'=>'Logg inn med %1$s','Log in with %1$s on the Wordpress login page'=>'Logg inn med %1$s på innloggingssiden i WordPress','Log in with %1$s!'=>'Logg inn med %1$s','Log in with %1$s-button'=>'Logg inn med %1$s-knapp','Logg inn med %1$s-logo'=>'Logg inn med %1$s-logo','Login'=>'Logg inn','Login method'=>'Innloggingsmåte','Login not confirmed: This user is not the user mapped to the %1$s account, and does not have the same email account'=>'Innlogging ikke bekreftet: Denne brukeren er ikke brukeren koblet til %1$s-kontoen og har ikke samme e-postkonto','Login with %1$s'=>'Innlogging med %1$s','Login with %1$s for WooCommerce'=>'Innlogging med %1$s for WooCommerce','Login with %1$s is disabled'=>'Innlogging med %1$s er slått av','Login with Vipps'=>'Innlogging med Vipps','Main options'=>'Hovedalternativer','Make the entire banner clickable'=>'Gjør hele banneret klikkbart','MobilePay'=>'MobilePay','No need to remember passwords ever again. Vipps, and you are logged in.'=>'Aldri mer brukernavn og passord. Vipps, så er du logget inn.','No, allow login without the app'=>'Nei, tillat innlogging uten å bruke appen','Normally, WooCommerce-banners like this will use a "click here"-text. If you don\'t, check here to make the entire banner clickable like a button'=>'Vanligvis så vil WooCommerce-bannere som dette bruke en "klikk her"-tekst. Hvis du ikke gjør dette, huk av her for å gjøre hele bannert klikkbart (som en knapp)','Norway'=>'Norge','Norwegian'=>'Norsk','Not a valid user'=>'Ikke en gyldig bruker','Only if member of restricted groups'=>'Bare hvis medlem i begrensede grupper','Press here to connect with your app'=>'Trykk her for å koble til med appen din','Primary'=>'Primær','Require this user to confirm their login with %1$s if logging in normally'=>'Krev at denne brukeren bekrefter innloggingen sin med %1$s hvis brukeren logger inn på vanlig måte','Require users in these roles to log in with %1$s'=>'Krev at brukere med følgende roller logger inn med %1$s','Rounded'=>'Avrundet','Save changes'=>'Lagre endringene','Session expired - please retry.'=>'Økten er utløpt - vennligst forsøk på nytt','Settings saved'=>'Innstillinger lagret','Show'=>'Vis','Show "Continue with %1$s" in Cart page and widgets'=>'Vis "Fortsett med %1$s" på handlekurvsiden og i widgeter','Show "Continue with %1$s" on the Checkout page'=>'Vis "Fortsett med %1$s" på kassesiden','Site language'=>'Nettstedsspråk','Sometimes, the user may need to confirm their email or answer follow up questions to complete sign in. This page, which you may leave blank, will be used for this purpose. A blank page will have been installed for you when activating the plugin, this is the default page which will be used. Do *not* use any system pages or anything that is being used for other things.'=>'Av og til vil brukeren måtte bekrefte e-postadressen sin eller svare på oppfølgingsspørsmål for å fullføre innlogging. Denne siden, som du kan la være tom, vil bli brukt til dette formålet.  Når du installerte utvidelsen vil en slik side ha blitt opprettet for deg; dette er standardsiden som vil bli brukt. Hvis du velger en annen, så pass på å ikke bruke en systemside eller en side som brukes til hva som helst annet.','Sweden'=>'Sverige','Swedish'=>'Svensk','The "Continue with %1$s" banner will have slightly different text depending on context, and some of these are rather long. You can change these dynamically if using hooks and filters, or you can use this override to change the standard text.'=>'Banneret "Fortsett med %1$s" vil ha litt forskjellig tekst avhengig av konteksten og noen av disse er ganske lange. Du kan endre dynamisk om du bruker knagger og filtre, eller du kan bruke overstyringen her til å endre standardteksten.','The code passed is invalid.'=>'Koden som ble sendt inn er ugyldig','The continue with %1$s-button can perform different actions depending on what is defined in your system. Per default it will log you in to WordPress or WooCommerce if installed, but plugins and themes can define more'=>'Knappen "Fortsett med %1$s" kan gjøre forskjellige ting avhengig av hva som er definert i ditt system. Som standard vil den logge deg inn i WordPress, eller WooCommerce om den er installert, men utvidelser og temaer kan definere flere.','The easiest way to log in. Anyone with %1$s can use %1$s to log in. No need to remember passwords ever again.'=>'Den enkleste måten å logge inn på. Alle med %1$s kan bruke %1$s for å logge inn. Aldri mer behov for å huske passord.','The user is connected to the %1$s profile with the phone number <b>%2$s</b>'=>'Denne brukeren er koblet til %1$s-profilen med telefonnummer <b>%2$s</b>','The user is not connected to a %1$s profile.'=>'Brukeren er ikke koblet til en %1$s-profil.','There is a problem with verifying your ID token from %1$s. Unfortunately, you cannot continue with %1$s at this time.'=>'Det er et problem med verifisering av din ID-token fra %1$s. Du kan dessverre ikke fortsette med %1$s nå.','This can only be called when logged in'=>'Dette er bare mulig å gjøre når du er logget inn.','This page is used to handle your requests when continuing from %1$s and further action is required to complete your task. But in this case, it doesn\'t seem to be an open session'=>'Denne siden brukes når du fortsetter fra %1$s, men det kreves en ytterligere handling for å bekrefte og fullføre oppgaven din. I dette tilfellet ser det ut som om økten har utløpt.','This will be used as the title/popup of the button'=>'Dette vil bli brukt som tittel/popup på knappen','This will replace Express Checkout on the checkout page.'=>'Dette vil erstatte hurtigkassen på kassesiden','Title'=>'Tittel','Turn Login with %1$s on and off'=>'Slå Innlogging med %1$s av og på','Unfortunately, you cannot connect to this %1$s-profile: The email addresses are not the same.'=>'Du kan ikke koble til med denne Vipps-%1$s. E-postadressene er ikke like.','Unhandled error when using Continue with %1$s for action %2$s: %3$s'=>'En uhåndtert feil oppsto ved bruk av "Fortsett med %1$ss" for handlingen %2$s: %3$s','Unlink account'=>'Fjern tilknytningen','Unmapping user %2$d from %1$s'=>'Frakobler brukeren %2$d fra %1$s','Use %1$s to login to your account'=>'Bruk %1$s til å logge inn på kontoen din','User cancelled the login'=>'Brukeren avbryt innloggingen','Users in these roles *must* use login with %1$s. You can also require this for a given user on the profile page'=>'Brukerne med disse rollene *må* bruke %1$s ved innlogging. Du kan også kreve dette for bestemte brukere på profilsiden deres.','Variant'=>'Variant','Verb'=>'Verb','Vipps'=>'Vipps','Vipps MobilePay'=>'Vipps MobilePay','Vipps MobilePay admin submenu labelLogin with %s'=>'Logg inn med %s','WP-Hosting AS'=>'WP-Hosting AS','Welcome! If you see this page, an really unexpected error h